import java.util.*;

class Solution {
    public List<Integer> strangeSortList(List<Integer> lst) {
        if (lst.isEmpty()) {
            return lst;
        }

        Collections.sort(lst);
        List<Integer> result = new ArrayList<>();
        while (!lst.isEmpty()) {
            result.add(lst.remove(0)); // Add smallest
            if (!lst.isEmpty()) {
                result.add(lst.remove(lst.size() - 1)); // Add largest
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Solution solution = new Solution();

        System.out.println(solution.strangeSortList(new ArrayList<>(Arrays.asList(1, 2, 3, 4)))); // [1, 4, 2, 3]
        System.out.println(solution.strangeSortList(new ArrayList<>(Arrays.asList(5, 5, 5, 5)))); // [5, 5, 5, 5]
        System.out.println(solution.strangeSortList(new ArrayList<>())); // []
    }
